# (model, rows, {fk field: (parent model, parent natural key)}), parents first.
_SEED = (
    ("Prompt", _PROMPT_ROWS, {}),
    ("Mode", _MODE_ROWS, {}),
    ("Loop", _LOOP_ROWS, {"prompt": ("Prompt", "name")}),
)


def _seed_defaults(apps, schema_editor):
    alias = schema_editor.connection.alias
    for model_name, rows, fks in _SEED:
        model = apps.get_model("core", model_name)
        for row in rows:
            fields = dict(row)
            name = fields.pop("name")
            for field, (parent_name, parent_key) in fks.items():
                if fields[field] is not None:
                    parent = apps.get_model("core", parent_name)
                    fields[field] = parent.objects.using(alias).get(**{parent_key: fields[field]})
            model.objects.using(alias).get_or_create(name=name, defaults=fields)


def _unseed_defaults(apps, schema_editor):
    alias = schema_editor.connection.alias
    for model_name, rows, _fks in reversed(_SEED):
        apps.get_model("core", model_name).objects.using(alias).filter(name__in=[row["name"] for row in rows]).delete()


